{
  "candidates": [
    {
      "approach": "日常安好",
      "text": "陆女士，生日快乐。新的一岁愿您日常从容，身心安稳，愿您忙碌之余也能找到属于自己的宁静时光。"
    },
    {
      "approach": "未来心愿",
      "text": "陆女士，生日快乐。愿您在新的一年里，愿想皆成，步履轻盈，生活如您所期，自在如风。"
    },
    {
      "approach": "感谢陪伴与理念",
      "text": "陆女士，感谢您一直以来对LIUXU的陪伴与信任。愿新的一岁，留白之间，天地为序，愿您与美好不期而遇。"
    }
  ]
}
